  renderMainForm(){const choices=this.choices();const choice=this.selectedChoice();this.$('#main-plan-form').innerHTML=`<div class="form-grid"><label>本户主计划<select id="main-plan" aria-label="本户主计划"><option value="">选择已核验的计划</option>${choices.map(c=>`<option value="${esc(this.choiceKey(c))}" ${this.choiceKey(c)===this.mainForm.key?'selected':''}>${esc(c.surface.name)} / ${esc(c.surface.plan_id)}</option>`).join('')}</select></label><label>本次调控动作<select id="main-action">${choice?list(choice.surface.actions).map(action=>`<option value="${esc(action)}" ${action===this.mainForm.action?'selected':''}>${esc(ACTIONS[action]||action)}</option>`).join(''):'<option value="">先选择计划</option>'}</select></label><label>调整后的设置值<input id="main-after" inputmode="decimal" autocomplete="off" value="${esc(this.mainForm.after)}" placeholder="填写明确新值" ${this.mainForm.action==='pause_plan'?'disabled':''}></label><label class="reason-field">本次原因<input id="main-reason" maxlength="500" autocomplete="off" value="${esc(this.mainForm.reason)}" placeholder="填写本次调整的具体依据"></label></div><p id="main-before" class="before-value"></p><div class="form-actions"><button id="prepare-main">准备这一条调控单</button><button id="clear-main" class="secondary">清空输入</button><span>准备后仍需核对确认，才会交由程序执行。</span></div>`;this.syncPrepare();}
