      const batchReady=this.state?.batch_control?.execution_available;
      const status=auto?(grant?'全自动执行已开启':state.running?(api||batchReady?'扫描中 · 逐批确认':this.state?.batch_control?'扫描中 · 等待批量执行连接':'扫描中 · 创建未接通'):'已停止'):(state.running?(ruleGrant?'运行中 · 全自动调控已授权':'运行中'):'已停止');
