  renderSettings(){const p=this.draft.profile;const number=(key,label,unit='')=>fieldHTML({label,key,type:'number',unit},getPath(p,key),key);const time=(key,label)=>`<label>${label}<input type="time" data-profile-path="${key}" value="${esc(getPath(p,key))}"></label>`;this.$('#runtime-fields').innerHTML=number('main_interval_seconds','主巡航周期','秒')+number('auto_interval_seconds','追投扫描周期','秒')+time('operation_start','允许操作开始')+time('operation_end','允许操作结束')+number('snapshot_max_age_seconds','快照最长有效期','秒')+`<label class="inline-check"><input type="checkbox" data-profile-path="broadcast_protection.enabled" ${p.broadcast_protection?.enabled?'checked':''}>启用停播保护</label>`+time('broadcast_protection.start','停播保护开始')+time('broadcast_protection.end','停播保护结束')+'<div class="settings-divider">操作限额与提醒</div>'+number('safety.max_actions_per_round','单轮动作上限','条')+number('safety.max_actions_per_day','单日动作上限','条')+number('safety.high_spend_no_orders','高消耗无成交提醒','元')+'<div class="settings-divider">现有Chrome页面绑定（留空时从已采集的本户页面识别）</div>'+['control_page_url','material_page_url'].map(key=>`<label class="url-field">${key==='control_page_url'?'调控任务页':'素材页'}<input type="url" data-binding="${key}" value="${esc(this.draft.bindings[key]||'')}" placeholder="https://qianchuan.jinritemai.com/…"></label>`).join('');}
