  renderFeatureAutomation(){const root=this.$('#feature-automation-state'),a=this.account();if(!root||!a)return;const api=this.state?.monitoring?.accounts?.some(m=>m.account_id===a.id&&m.backend==='official_api');if(!api){root.innerHTML='';return;}const g=list(this.state?.api_rule_auto).find(g=>g.account_id===a.id&&g.enabled&&g.profile_revision===a.revision),chase=list(this.state?.api_auto).find(g=>g.account_id===a.id&&g.enabled),fid=this.feature,authorized=fid==='f5'?Boolean(chase):Boolean(g),reasons=[...new Set(list(g?.diagnostics).filter(d=>d.feature_id===fid).map(d=>d.reason).filter(Boolean))];root.innerHTML=`<p class="capability-note"><strong>${esc(fid.toUpperCase())} · ${authorized?'全自动已授权':'尚未开启自动执行'}</strong> · ${a.profile?.features?.[fid]?.enabled?'规则已启用':'规则未启用'}${reasons.length?' · '+esc(reasons.join('；')):authorized?' · 等待本轮条件检查':' · 逐单确认模式，可在主计划调控开启本户六项全自动授权'}${this.dirty?' · 当前修改尚未保存':''}</p>`;}
